static void inpu_fromBlockedLayoutTransform(const real32_T *inputTensor,
  real32_T *outputTensor)
{
  int32_T fusedImageIdx;
  int32_T imageIdx;
  for (fusedImageIdx = 0; fusedImageIdx < 800; fusedImageIdx++) {
    int32_T blockIdx;
    int32_T fusedBlockIdx;
    int32_T fusedWidthAndHeightIdx;
    imageIdx = div_nde_s32_floor(fusedImageIdx, 800);
    fusedBlockIdx = fusedImageIdx % 800;
    blockIdx = div_nde_s32_floor(fusedBlockIdx, 50);
    fusedWidthAndHeightIdx = fusedBlockIdx % 50;
    fusedBlockIdx = (blockIdx * 200 + imageIdx * 3200) + fusedWidthAndHeightIdx;
    blockIdx = (blockIdx * 200 + (fusedWidthAndHeightIdx << 2)) + imageIdx *
      3200;
    for (imageIdx = 1; imageIdx < 5; imageIdx++) {
      outputTensor[fusedBlockIdx + (imageIdx - 1) * 50] = inputTensor[(blockIdx
        + imageIdx) - 1];
    }
  }
}

